<?php
session_start(); header('Content-Type: application/json; charset=utf-8'); require dirname(__DIR__).'/db.php';
$d=json_decode(file_get_contents('php://input'),true)?:[];$items=$d['items']??[];$name=trim($d['name']??'');$phone=trim($d['phone']??'');$email=strtolower(trim($d['email']??''));
if(!$name||!$phone||!$items){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Completează numele, telefonul și coșul.']);exit;}
if($email && !filter_var($email,FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Adresa de email nu este validă.']);exit;}
try{$pdo->beginTransaction();$total=0;$clean=[];$get=$pdo->prepare('SELECT id,name,price,stock,active FROM products WHERE id=? FOR UPDATE');foreach($items as $i){$id=(int)($i['id']??0);$qty=max(1,min(99,(int)($i['qty']??1)));$get->execute([$id]);$p=$get->fetch();if(!$p||!$p['active'])throw new Exception('Un produs nu mai este disponibil.');if((int)$p['stock']<$qty)throw new Exception('Stoc insuficient pentru '.$p['name'].'.');$total+=(float)$p['price']*$qty;$img=$i['personalization_image']??'';if(strlen($img)>2100000)$img='';$clean[]=[$p,$qty,mb_substr((string)($i['personalization']??''),0,1000),$img];}
$cid=$_SESSION['customer']??null;if($cid && !$email){$s=$pdo->prepare('SELECT email FROM customers WHERE id=?');$s->execute([$cid]);$email=(string)$s->fetchColumn();}
$s=$pdo->prepare('INSERT INTO orders(customer_id,customer_name,email,phone,address,details,total) VALUES(?,?,?,?,?,?,?)');$s->execute([$cid,$name,$email?:null,$phone,trim($d['address']??''),trim($d['details']??''),$total]);$oid=$pdo->query("SELECT LASTVAL()")->fetchColumn();$si=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,qty,price,personalization,personalization_image) VALUES(?,?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($clean as [$p,$qty,$txt,$img]){$si->execute([$oid,$p['id'],$p['name'],$qty,$p['price'],$txt,$img?:null]);$stock->execute([$qty,$p['id']]);}$pdo->commit();echo json_encode(['ok'=>true,'order_id'=>$oid,'total'=>$total]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()?:'Comanda nu a putut fi salvată.']);}
